#nullable enable
using Microsoft.Extensions.DependencyInjection;
using EmailOutbox.Contracts;
using EmailOutbox.Slices.EmailOutbox;
using EmailOutbox.Views;
using Marten;
using Shouldly;
using Wolverine;
using Xunit;

namespace EmailOutbox.IntegrationTests.Slices.EmailOutbox;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation — which is the only reason these tests
/// mean anything. Pattern: automation. Status: ready. LIVE, so every test here must pass.
///
/// EVERY WAKEUP MECHANISM MUST SATISFY THESE UNCHANGED. That is what makes this folder a comparison rather
/// than four different programs: the rules come from one model, and only the thing that sends
/// <see cref="RunSendEmail"/> differs.
///
/// The WHEN is not an HTTP post. This slice's command is issued by the trigger, in process, so the test
/// issues it the same way. The generated scaffold guessed at "a 400 with ProblemDetails" for the rejections
/// because the generator cannot tell an automation's command from a typed one — a real limitation of the
/// kit, and the reason a rejection here is a <see cref="SendOutcome"/> instead.
/// </summary>
public sealed class SendEmailTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static Guid Stream => SendEmailState.StreamKey(SeedData.EmailId);

    private static EmailPrepared Prepared => new(
        SeedData.EmailId, "someone@example.com", "Subject", "Body", SeedData.SeededAt);

    /// <summary>WHEN the command alone, straight to the decider — a GWT's when= names a COMMAND.</summary>
    private async Task<SendOutcome> Send(Guid emailId)
    {
        using var scope = Host.Services.CreateScope();
        var bus = scope.ServiceProvider.GetRequiredService<IMessageBus>();
        return await bus.InvokeAsync<SendOutcome>(new SendEmail(emailId));
    }

    /// <summary>WHEN the trigger runs: one pass over the todo View. What every mechanism ends up doing.</summary>
    private async Task Run()
    {
        using var scope = Host.Services.CreateScope();
        await scope.ServiceProvider.GetRequiredService<IMessageBus>().InvokeAsync(new RunSendEmail());
    }

    /// <summary>
    /// Loaded by STREAM KEY, not by emailId — and that gap is worth knowing.
    ///
    /// The model declares identity="emailId" on the view, and the generator correctly reads that as "one row
    /// per stream" and picks SingleStreamProjection. But Marten then keys the document by the stream key
    /// itself, which here is "email:{guid}" and not the bare guid. The declared grain and the physical id
    /// are 1:1 and NOT equal, so LoadAsync(emailId.ToString()) silently returns null — which surfaces as a
    /// NullReferenceException in a test rather than as anything explaining itself.
    /// </summary>
    private async Task<EmailsToSend?> Row(Guid emailId)
    {
        await using var session = Store.QuerySession();
        return await session.LoadAsync<EmailsToSend>(SendEmailState.StreamKey(emailId));
    }

    // a prepared email is sent
    //   GIVEN EmailPrepared
    //   WHEN  SendEmail
    //   THEN  EmailSent
    [Fact]
    public async Task APreparedEmailIsSent()
    {
        await Given(Stream, Prepared);

        var outcome = await Send(SeedData.EmailId);

        outcome.WasSent.ShouldBeTrue();
        outcome.Rule.ShouldBeNull();
        outcome.ProviderMessageId.ShouldNotBeNullOrWhiteSpace();

        var sent = (await EventsFor(Stream)).OfType<EmailSent>().ShouldHaveSingleItem();
        sent.EmailId.ShouldBe(SeedData.EmailId);
        sent.ProviderMessageId.ShouldBe(outcome.ProviderMessageId);

        // The todo row is ticked off by the event, which is what stops a second run picking it up. The
        // projection is Inline, so this is assertable the moment the append returns.
        (await Row(SeedData.EmailId))!.Status.ShouldBe(EmailsToSend.Sent);
    }

    // an email already sent is not sent twice
    //   GIVEN EmailPrepared, EmailSent
    //   WHEN  SendEmail
    //   THEN  error: AlreadySent
    [Fact]
    public async Task AnEmailAlreadySentIsNotSentTwice()
    {
        // A GIVEN is history, appended straight to the stream — not requests to replay.
        await Given(Stream, Prepared,
            new EmailSent(SeedData.EmailId, "prov-original", SeedData.SeededAt));

        var outcome = await Send(SeedData.EmailId);

        outcome.WasSent.ShouldBeFalse();
        outcome.Rule.ShouldBe("AlreadySent");

        // The original stands and nothing was appended beside it. This is the rule the whole comparison
        // rests on: every mechanism here is at-least-once, so without it they would differ only in how fast
        // they send duplicates.
        var sent = (await EventsFor(Stream)).OfType<EmailSent>().ShouldHaveSingleItem();
        sent.ProviderMessageId.ShouldBe("prov-original");
    }

    // an email nobody prepared cannot be sent
    //   GIVEN (nothing)
    //   WHEN  SendEmail
    //   THEN  error: NotPrepared
    [Fact]
    public async Task AnEmailNobodyPreparedCannotBeSent()
    {
        // No GIVEN at all. An empty stream folds to a default instance, so "nobody prepared this" and "this
        // email does not exist" are the same state — which is why one check covers both, and why the rule
        // cannot live in a validator even though its given= is blank.
        var outcome = await Send(Guid.NewGuid());

        outcome.WasSent.ShouldBeFalse();
        outcome.Rule.ShouldBe("NotPrepared");
    }

    /// <summary>
    /// NOT a GWT — the model says nothing about transport and should not. This is the property that makes
    /// the four wakeup mechanisms interchangeable: running the trigger repeatedly must be safe, so
    /// correctness never depends on how often, or how many times, something fires.
    /// </summary>
    [Fact]
    public async Task RunningTheTriggerRepeatedlyIsSafe()
    {
        await Given(Stream, Prepared);

        await Run();
        var afterFirst = (await EventsFor(Stream)).OfType<EmailSent>().ShouldHaveSingleItem();

        await Run();
        await Run();

        // Still exactly one send, and the same one. The extra runs find the row already Sent and the decider
        // refuses anyway — belt and braces on purpose, because the View is a convenience and the stream is
        // the truth.
        var afterThree = (await EventsFor(Stream)).OfType<EmailSent>().ShouldHaveSingleItem();
        afterThree.ProviderMessageId.ShouldBe(afterFirst.ProviderMessageId);
    }
}
